//! Exact heads-up river solver: vector-form CFR+ over the 1326 hole pairs.
//!
//! Self-contained (no third-party solver code). The betting tree is generated by the `nlhe`
//! engine from a [`BetSizing`] menu, so a tested policy can be queried at exactly the same
//! states. Everything is `f64`; utilities are chips won from the start of the hand (money
//! already in the pot is sunk), so a showdown winner gains the loser's contribution.
//!
//! * [`Ctx`]: per-board hand ranks and O(n) showdown / fold evaluation with card removal
//!   (sort by rank, prefix sums per card; inclusion-exclusion on the two hole cards).
//! * [`Tree`]: betting tree (player 0 = OOP, player 1 = IP).
//! * [`Solver`]: simultaneous-update CFR+ with linear averaging.
//! * [`Game::best_response`] / [`Game::ev_loss`]: exact BR against any fixed [`Strategy`].
//!
//! EV values are normalised by the total compatible range mass `Z`, i.e. they are expected
//! chips for a random deal of both ranges.

use cards::{all_holes, bit, evaluate, mask_of, Card};
use nlhe::abstraction::{abstract_actions, ActionList, BetSizing};
use nlhe::{Action, State, Step};

pub const N: usize = 1326;

/// Per-board hand data.
pub struct Ctx {
    pub board: [Card; 5],
    pub cards: Vec<[u8; 2]>,
    pub valid: Vec<bool>,
    pub rank: Vec<u32>,
    /// Valid hands ascending by rank, split into tie groups.
    order: Vec<u16>,
    groups: Vec<(usize, usize)>,
}

impl Ctx {
    pub fn new(board: [Card; 5]) -> Ctx {
        let holes = all_holes();
        let bm = mask_of(&board);
        let mut valid = vec![false; N];
        let mut rank = vec![0u32; N];
        let mut cards = vec![[0u8; 2]; N];
        for (i, h) in holes.iter().enumerate() {
            cards[i] = *h;
            if bit(h[0]) & bm == 0 && bit(h[1]) & bm == 0 {
                valid[i] = true;
                rank[i] = evaluate(bit(h[0]) | bit(h[1]) | bm);
            }
        }
        let mut order: Vec<u16> = (0..N as u16).filter(|&i| valid[i as usize]).collect();
        order.sort_by_key(|&i| rank[i as usize]);
        let mut groups = Vec::new();
        let mut s = 0;
        for i in 1..=order.len() {
            if i == order.len() || rank[order[i] as usize] != rank[order[s] as usize] {
                groups.push((s, i));
                s = i;
            }
        }
        Ctx {
            board,
            cards,
            valid,
            rank,
            order,
            groups,
        }
    }

    /// Zero out hands that collide with the board.
    pub fn mask(&self, r: &mut [f64]) {
        for i in 0..N {
            if !self.valid[i] {
                r[i] = 0.0;
            }
        }
    }

    fn card_sums(&self, r: &[f64]) -> (f64, [f64; 52]) {
        let mut t = 0.0;
        let mut c = [0.0; 52];
        for i in 0..N {
            if r[i] != 0.0 {
                t += r[i];
                c[self.cards[i][0] as usize] += r[i];
                c[self.cards[i][1] as usize] += r[i];
            }
        }
        (t, c)
    }

    /// `out[h]` = sum of `r[h']` over hands `h'` that do not share a card with `h`.
    pub fn compat(&self, r: &[f64], out: &mut [f64]) {
        let (t, c) = self.card_sums(r);
        for i in 0..N {
            out[i] = if self.valid[i] {
                let [a, b] = self.cards[i];
                t - c[a as usize] - c[b as usize] + r[i]
            } else {
                0.0
            };
        }
    }

    /// Showdown counterfactual values for the holder: `amount * (P(win) - P(lose))` weighted
    /// by the opponent reach `r` (ties pay nothing).
    pub fn showdown(&self, r: &[f64], amount: f64, out: &mut [f64]) {
        let (tot, tc) = self.card_sums(r);
        let mut less = 0.0;
        let mut lc = [0.0f64; 52];
        out.iter_mut().for_each(|x| *x = 0.0);
        for &(s, e) in &self.groups {
            let mut gt = 0.0;
            let mut gc = [0.0f64; 52];
            for &h in &self.order[s..e] {
                let h = h as usize;
                gt += r[h];
                gc[self.cards[h][0] as usize] += r[h];
                gc[self.cards[h][1] as usize] += r[h];
            }
            for &h in &self.order[s..e] {
                let h = h as usize;
                let [a, b] = [self.cards[h][0] as usize, self.cards[h][1] as usize];
                let comp_less = less - lc[a] - lc[b];
                let comp_eq = gt - gc[a] - gc[b] + r[h];
                let comp_all = tot - tc[a] - tc[b] + r[h];
                let greater = comp_all - comp_less - comp_eq;
                out[h] = amount * (comp_less - greater);
            }
            for &h in &self.order[s..e] {
                let h = h as usize;
                less += r[h];
                lc[self.cards[h][0] as usize] += r[h];
                lc[self.cards[h][1] as usize] += r[h];
            }
        }
    }
}

#[derive(Clone, Debug)]
pub enum Kind {
    Action {
        player: usize,
        acts: Vec<Action>,
        kids: Vec<usize>,
    },
    /// `folder` (player index) loses `amount`.
    Fold { folder: usize, amount: f64 },
    /// Showdown for `amount` (the smaller contribution).
    Showdown { amount: f64 },
}

#[derive(Clone, Debug)]
pub struct Node {
    pub kind: Kind,
    /// Engine state at this node (before the acting player moves).
    pub state: State,
    /// Actions taken from the root.
    pub path: Vec<Action>,
}

pub struct Tree {
    pub nodes: Vec<Node>,
    pub seats: [usize; 2],
}

impl Tree {
    /// Build from a river decision state. `seats = [oop, ip]`.
    pub fn build(root: State, seats: [usize; 2], sizing: &BetSizing) -> Result<Tree, String> {
        if root.is_terminal() || root.street() != nlhe::Street::River {
            return Err("root must be a river decision".into());
        }
        let mut t = Tree {
            nodes: Vec::new(),
            seats,
        };
        t.rec(root, vec![], sizing)?;
        Ok(t)
    }

    fn rec(&mut self, st: State, path: Vec<Action>, sizing: &BetSizing) -> Result<usize, String> {
        let id = self.nodes.len();
        let kind = if st.is_terminal() {
            let [a, b] = self.seats;
            if st.showdown() {
                Kind::Showdown {
                    amount: st.contributed(a).min(st.contributed(b)) as f64,
                }
            } else {
                let folder = if st.is_folded(a) { 0 } else { 1 };
                Kind::Fold {
                    folder,
                    amount: st.contributed(self.seats[folder]) as f64,
                }
            }
        } else {
            let seat = st.to_act().unwrap();
            let player = self
                .seats
                .iter()
                .position(|&s| s == seat)
                .ok_or("unexpected seat in river tree")?;
            let mut list = ActionList::new();
            abstract_actions(&st, sizing, &mut list);
            Kind::Action {
                player,
                acts: list.as_slice().to_vec(),
                kids: vec![],
            }
        };
        self.nodes.push(Node {
            kind: kind.clone(),
            state: st,
            path: path.clone(),
        });
        if let Kind::Action { acts, .. } = kind {
            let mut kids = Vec::new();
            for &a in &acts {
                let mut s2 = st;
                if let Step::NewStreet(_) = s2.apply(a) {
                    return Err("street change inside river tree".into());
                }
                let mut p2 = path.clone();
                p2.push(a);
                kids.push(self.rec(s2, p2, sizing)?);
            }
            if let Kind::Action { kids: k, .. } = &mut self.nodes[id].kind {
                *k = kids;
            }
        }
        Ok(id)
    }

    pub fn action_nodes(&self) -> impl Iterator<Item = usize> + '_ {
        (0..self.nodes.len()).filter(|&i| matches!(self.nodes[i].kind, Kind::Action { .. }))
    }
}

/// Per node, `n_actions * N` probabilities laid out `[a * N + h]`. Empty for terminals.
#[derive(Clone, Debug)]
pub struct Strategy(pub Vec<Vec<f64>>);

impl Strategy {
    /// Build from `f(node_id, action_index, n_actions, hand) -> weight`, normalised per hand.
    pub fn from_fn(tree: &Tree, mut f: impl FnMut(usize, usize, usize, usize) -> f64) -> Strategy {
        let mut v = vec![Vec::new(); tree.nodes.len()];
        for id in tree.action_nodes() {
            let Kind::Action { acts, .. } = &tree.nodes[id].kind else {
                unreachable!()
            };
            let n = acts.len();
            let mut s = vec![0.0; n * N];
            for h in 0..N {
                let mut tot = 0.0;
                for a in 0..n {
                    let w = f(id, a, n, h).max(0.0);
                    s[a * N + h] = w;
                    tot += w;
                }
                for a in 0..n {
                    s[a * N + h] = if tot > 0.0 {
                        s[a * N + h] / tot
                    } else {
                        1.0 / n as f64
                    };
                }
            }
            v[id] = s;
        }
        Strategy(v)
    }
}

pub struct Game {
    pub ctx: Ctx,
    pub tree: Tree,
    /// Range weights per player (0 = OOP, 1 = IP), masked to valid hands.
    pub range: [Vec<f64>; 2],
    /// Total compatible mass.
    pub z: f64,
    pub bb: f64,
}

impl Game {
    pub fn new(
        root: State,
        seats: [usize; 2],
        board: [Card; 5],
        mut range: [Vec<f64>; 2],
        sizing: &BetSizing,
        bb: i32,
    ) -> Result<Game, String> {
        let ctx = Ctx::new(board);
        for r in range.iter_mut() {
            ctx.mask(r);
        }
        let tree = Tree::build(root, seats, sizing)?;
        let mut c = vec![0.0; N];
        ctx.compat(&range[1], &mut c);
        let z: f64 = (0..N).map(|h| range[0][h] * c[h]).sum();
        if z <= 0.0 {
            return Err("empty compatible ranges".into());
        }
        Ok(Game {
            ctx,
            tree,
            range,
            z,
            bb: bb as f64,
        })
    }

    fn terminal(&self, id: usize, reach: [&[f64]; 2]) -> Option<[Vec<f64>; 2]> {
        match &self.tree.nodes[id].kind {
            Kind::Showdown { amount } => {
                let (mut a, mut b) = (vec![0.0; N], vec![0.0; N]);
                self.ctx.showdown(reach[1], *amount, &mut a);
                self.ctx.showdown(reach[0], *amount, &mut b);
                Some([a, b])
            }
            Kind::Fold { folder, amount } => {
                let w = 1 - folder;
                let mut cf = vec![0.0; N];
                let mut cw = vec![0.0; N];
                self.ctx.compat(reach[w], &mut cf); // folder's view: compatible winner reach
                self.ctx.compat(reach[*folder], &mut cw);
                cf.iter_mut().for_each(|x| *x *= -amount);
                cw.iter_mut().for_each(|x| *x *= *amount);
                let mut out = [Vec::new(), Vec::new()];
                out[*folder] = cf;
                out[w] = cw;
                Some(out)
            }
            Kind::Action { .. } => None,
        }
    }

    /// Counterfactual values of a fixed profile.
    fn eval(&self, s: &Strategy, id: usize, reach: [&[f64]; 2]) -> [Vec<f64>; 2] {
        if let Some(v) = self.terminal(id, reach) {
            return v;
        }
        let Kind::Action {
            player: p, kids, ..
        } = &self.tree.nodes[id].kind
        else {
            unreachable!()
        };
        let q = 1 - p;
        let sig = &s.0[id];
        let (mut vp, mut vq) = (vec![0.0; N], vec![0.0; N]);
        for (a, &k) in kids.iter().enumerate() {
            let nr: Vec<f64> = (0..N).map(|h| reach[*p][h] * sig[a * N + h]).collect();
            let mut r2 = reach;
            r2[*p] = &nr;
            let c = self.eval(s, k, r2);
            for h in 0..N {
                vp[h] += sig[a * N + h] * c[*p][h];
                vq[h] += c[q][h];
            }
        }
        let mut out = [Vec::new(), Vec::new()];
        out[*p] = vp;
        out[q] = vq;
        out
    }

    /// Expected chips per player when both follow `s` (random deal of the ranges).
    pub fn value(&self, s: &Strategy) -> [f64; 2] {
        let v = self.eval(s, 0, [&self.range[0], &self.range[1]]);
        [0, 1].map(|p| (0..N).map(|h| self.range[p][h] * v[p][h]).sum::<f64>() / self.z)
    }

    fn br(&self, id: usize, p: usize, opp: &Strategy, opp_reach: &[f64]) -> Vec<f64> {
        let q = 1 - p;
        // terminals: BR player's own reach is irrelevant to its cfv, pass dummy
        let dummy = vec![0.0; N];
        let mut reach: [&[f64]; 2] = [&dummy, &dummy];
        reach[q] = opp_reach;
        if let Some(v) = self.terminal(id, reach) {
            return v.into_iter().nth(p).unwrap();
        }
        let Kind::Action { player, kids, .. } = &self.tree.nodes[id].kind else {
            unreachable!()
        };
        if *player == p {
            let mut best = vec![f64::NEG_INFINITY; N];
            for &k in kids {
                let c = self.br(k, p, opp, opp_reach);
                for h in 0..N {
                    best[h] = best[h].max(c[h]);
                }
            }
            best
        } else {
            let sig = &opp.0[id];
            let mut sum = vec![0.0; N];
            for (a, &k) in kids.iter().enumerate() {
                let nr: Vec<f64> = (0..N).map(|h| opp_reach[h] * sig[a * N + h]).collect();
                let c = self.br(k, p, opp, &nr);
                for h in 0..N {
                    sum[h] += c[h];
                }
            }
            sum
        }
    }

    /// Expected chips of player `p` best-responding to the other player's part of `s`.
    pub fn best_response(&self, s: &Strategy, p: usize) -> f64 {
        let v = self.br(0, p, s, &self.range[1 - p]);
        (0..N).map(|h| self.range[p][h] * v[h]).sum::<f64>() / self.z
    }

    /// Exploitability in chips: `(BR_0 + BR_1)` summed over both seats' best responses
    /// (0 at equilibrium since the game is zero-sum).
    pub fn exploitability(&self, s: &Strategy) -> f64 {
        (self.best_response(s, 0) + self.best_response(s, 1)) / 2.0
    }

    /// EV loss of each player's strategy in `s` versus the reference equilibrium `eq`, in mbb:
    /// `value_p(eq) + BR_other(s_p)`. Zero (up to solver error) for an equilibrium strategy.
    pub fn ev_loss(&self, s: &Strategy, eq: &Strategy) -> [f64; 2] {
        let v = self.value(eq);
        [0, 1].map(|p| (v[p] + self.best_response(s, 1 - p)) * 1000.0 / self.bb)
    }

    /// Run `iters` iterations of CFR+ (linear averaging); returns the average strategy.
    pub fn solve(&self, iters: usize) -> Strategy {
        let mut sv = Solver::new(self);
        for _ in 0..iters {
            sv.iterate();
        }
        sv.average()
    }
}

pub struct Solver<'g> {
    g: &'g Game,
    regret: Vec<Vec<f64>>,
    ssum: Vec<Vec<f64>>,
    t: f64,
}

impl<'g> Solver<'g> {
    pub fn new(g: &'g Game) -> Self {
        let mut regret = vec![Vec::new(); g.tree.nodes.len()];
        for id in g.tree.action_nodes() {
            if let Kind::Action { acts, .. } = &g.tree.nodes[id].kind {
                regret[id] = vec![0.0; acts.len() * N];
            }
        }
        Solver {
            g,
            ssum: regret.clone(),
            regret,
            t: 0.0,
        }
    }

    fn sigma(&self, id: usize, n: usize) -> Vec<f64> {
        let r = &self.regret[id];
        let mut s = vec![0.0; n * N];
        for h in 0..N {
            let tot: f64 = (0..n).map(|a| r[a * N + h]).sum();
            for a in 0..n {
                s[a * N + h] = if tot > 0.0 {
                    r[a * N + h] / tot
                } else {
                    1.0 / n as f64
                };
            }
        }
        s
    }

    pub fn iterate(&mut self) {
        self.t += 1.0;
        let g = self.g;
        self.walk(0, [&g.range[0], &g.range[1]]);
    }

    fn walk(&mut self, id: usize, reach: [&[f64]; 2]) -> [Vec<f64>; 2] {
        let g = self.g;
        if let Some(v) = g.terminal(id, reach) {
            return v;
        }
        let Kind::Action {
            player: p,
            kids,
            acts,
        } = &g.tree.nodes[id].kind
        else {
            unreachable!()
        };
        let (p, q, n) = (*p, 1 - *p, acts.len());
        let sig = self.sigma(id, n);
        let mut vp = vec![0.0; N];
        let mut vq = vec![0.0; N];
        let mut cp: Vec<Vec<f64>> = Vec::with_capacity(n);
        for (a, &k) in kids.iter().enumerate() {
            let nr: Vec<f64> = (0..N).map(|h| reach[p][h] * sig[a * N + h]).collect();
            let mut r2 = reach;
            r2[p] = &nr;
            let mut c = self.walk(k, r2);
            for h in 0..N {
                vp[h] += sig[a * N + h] * c[p][h];
                vq[h] += c[q][h];
            }
            cp.push(std::mem::take(&mut c[p]));
        }
        let (reg, ss) = (&mut self.regret[id], &mut self.ssum[id]);
        for a in 0..n {
            for h in 0..N {
                let i = a * N + h;
                reg[i] = (reg[i] + cp[a][h] - vp[h]).max(0.0);
                ss[i] += self.t * reach[p][h] * sig[i];
            }
        }
        let mut out = [Vec::new(), Vec::new()];
        out[p] = vp;
        out[q] = vq;
        out
    }

    /// Average strategy (uniform where a hand was never reached).
    pub fn average(&self) -> Strategy {
        let g = self.g;
        let mut v = vec![Vec::new(); g.tree.nodes.len()];
        for id in g.tree.action_nodes() {
            let n = self.ssum[id].len() / N;
            let mut s = vec![0.0; n * N];
            for h in 0..N {
                let tot: f64 = (0..n).map(|a| self.ssum[id][a * N + h]).sum();
                for a in 0..n {
                    s[a * N + h] = if tot > 0.0 {
                        self.ssum[id][a * N + h] / tot
                    } else {
                        1.0 / n as f64
                    };
                }
            }
            v[id] = s;
        }
        Strategy(v)
    }
}

/// Reference O(n^2) showdown values (tests).
pub fn showdown_brute(ctx: &Ctx, r: &[f64], amount: f64) -> Vec<f64> {
    let mut out = vec![0.0; N];
    for h in 0..N {
        if !ctx.valid[h] {
            continue;
        }
        for o in 0..N {
            if !ctx.valid[o] || r[o] == 0.0 {
                continue;
            }
            let (a, b) = (ctx.cards[h], ctx.cards[o]);
            if a[0] == b[0] || a[0] == b[1] || a[1] == b[0] || a[1] == b[1] {
                continue;
            }
            out[h] += r[o] * amount * (ctx.rank[h].cmp(&ctx.rank[o]) as i32 as f64);
        }
    }
    out
}
